    val pagina: Int = 0,
    val fonte: String = "Livro de Regras",
)

val AMEACAS_PRONTAS: List<AmeacaPronta> = listOf(
    AmeacaPronta(nome = "Alvira", vd = "120", elemento = "Sangue", defesa = 26, pv = 210, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 1, "int" to 2, "pre" to 4, "vig" to 2), ataques = "TESTE O+15 | DANO 2d12+10 corte (Cruz de Sangue, corpo a corpo x2)", detalhes = "MADRE SUPERIOR: um aliado adjacente pode gastar ação de movimento para sugar seu sangue, causando-lhe 3d8+3 de dano; o aliado se cura na mesma quantidade (metade se Alvira estiver machucada); indisponível se estiver morrendo. RITUAIS (DT 23): conjura Vampirismo Sangue 2 sem pagar PE, até 10 PE por conjuração. SUSSURRO HORRIPILANTE: sua voz ressoa em alcance longo com efeito de presença perturbadora (DT 23, 4d6 mental, NEX 50% imune). CLAMOR DO SANGUE DIVINO: uma vez por cena, dá +O em testes de Agilidade, Força ou Vigor a todos em alcance longo escolhidos por ela até o fim da cena. BOLSA DE SANGUE: dá 3d8+3 PV (podendo virar PV temporários) a um ser em alcance longo. TITEREIRA DE SANGUE: cria cordas de Sangue que controlam um ser em alcance longo que já tenha bebido ou sido curado por seu sangue; o alvo gasta todas as ações obedecendo (Fortitude DT 23 evita, repetível a cada turno). TRANSFERIR SANGUE: uma vez por rodada, regurgita sangue em um adjacente, sofrendo 3d8+3 de dano e curando o alvo na mesma quantidade (metade se machucada); o alvo pode evitar com Reflexos DT 23.", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Apóstata", vd = "80", elemento = "Conhecimento/Morte", defesa = 23, pv = 111, deslocamento = 0, atributos = mapOf("agi" to 3, "for" to 3, "int" to 2, "pre" to 2, "vig" to 3), ataques = "TESTE 3O+10 | DANO 6d10 mental (Flagellum, distância curto)", detalhes = "MENTEM CORRUMPERE: quem falha contra sua presença perturbadora pode, à escolha da apóstata, não sofrer dano mental e em vez disso ser contaminado por uma crença impossível (doença em quatro estágios progressivos, sem teste de resistência inicial; a cada dia, Vontade DT 20+1/dia infectado ou fica compelido a não se afastar mais de 90m dela). MURUS IDOLORUM: esconde-se atrás de uma parede de ídolos; atravessá-la causa 20d12 de dano de Conhecimento (0 PV = inexistido, morte instantânea). RITUS: subjuga fiéis a completar ritos (testes estendidos de Religião DT crescente) que avançam os estágios da doença e aumentam o VD da apóstata de 80 para 160, 240 e 320, com bônus crescentes em testes/dano/RD e novas ações (Gnosis Implicata, Gnosis Absoluta, Visio Vetita, Vacuitatem Observa). FUNES LIGANTES: pode agarrar com fios ao acertar Flagellum (teste 3O+15), mantendo até dois presos. Enigma de Medo: enquanto protegida pelos ídolos é imune e não pode ser derrotada definitivamente; só interrompendo um rito antes da conclusão ela é forçada a revelar sua forma verdadeira (perde imunidades, ganha deslocamento 9m|6 por 3 rodadas).", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Incinerado", vd = "60", elemento = "Energia/Sangue", defesa = 21, pv = 100, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 3, "int" to 0, "pre" to 0, "vig" to 2), ataques = "TESTE 3O+10 | DANO 2d8+5 fogo, alvo fica em chamas (Disparo de Labaredas, distância curto x2)", detalhes = "COMBUSTÃO CAÓTICA: perde 10 PV no início de cada turno; ao ficar machucado, passa a ter duas ações padrão em vez de uma enquanto durar essa condição. INSTABILIDADE ÍGNEA: ao chegar a 0 PV, explode em chamas caóticas num raio de 6m, causando 5d10 de dano (metade mental, metade Energia) e deixando em chamas quem estiver na área (Reflexos DT 19 reduz o dano à metade e evita a condição). AGONIA INCANDESCENTE: berro que causa 3d6 de dano mental num raio de 18m (Vontade DT 19 reduz à metade); alvos em chamas sofrem –5 no teste. ALIMENTAR AS CHAMAS: quando alguém sofre dano da condição em chamas em alcance curto, o incinerado recupera PV igual à metade do dano. CONSUMIDO PELO CAOS: um ser com SAN 0 ou 0 PV, em chamas e em alcance curto, é consumido pelo fogo, morre e vira um novo incinerado. Cadáver consumido pelo caos e pelas chamas, reerguido a partir de um corpo queimado onde a Membrana foi fragilizada pela Energia.", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "O Verdadeiro Raziel", vd = "200", elemento = "Sangue", defesa = 38, pv = 400, deslocamento = 12, atributos = mapOf("agi" to 3, "for" to 3, "int" to 2, "pre" to 2, "vig" to 3), ataques = "TESTE 4O+25, crítico 18 | DANO 5d10+30 perfuração (Garras, corpo a corpo x2)", detalhes = "Forma de Fúria Sanguinária que Raziel assume quando fica machucado ou enfurecido, a critério do mestre; se estava com menos de 200 PV, passa a ter exatamente 200. SEDE INCONTROLÁVEL: se Alvira estiver ameaçada, gasta todas as ações para matar quem a ameaça; senão, foca no alvo com menos PV na cena. REVIDAR E ESTRIPAR: uma vez por rodada, ao sofrer ataque corpo a corpo, revida com um ataque, perdendo suas RD por 1 rodada. ABRAÇO SANGUINOLENTO: acertando as garras, pode agarrar (teste 4O+15); uma vez por rodada, como ação livre, morde o agarrado causando 10d6 de dano de Sangue (Fortitude DT 29 reduz à metade) e recupera PV igual à metade do dano. PERSEGUIR: uma vez por rodada, percorre o dobro do deslocamento na direção de um alvo que quer matar. BOTE RETALHADOR: salta sobre um ser em até 3m; o alvo escolhe atacar (reação; se errar, sofre 10d10+30 de perfuração, cai e sangra; se acertar, reduz à metade e evita) ou tentar escapar (Reflexos DT 29; falha sofre o mesmo dano/condições, sucesso reduz à metade e evita).", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Raziel", vd = "120", elemento = "Sangue", defesa = 28, pv = 240, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 3, "int" to 3, "pre" to 2, "vig" to 3), ataques = "TESTE 4O+15, crítico 18 | DANO 2d10+20 perfuração (Garras, corpo a corpo x2)", detalhes = "IGNORAR DOR: nesta forma aparenta ser imune a dano (efeito apenas estético); um teste de Intuição ou Percepção DT 30 revela que não é real. VINGANÇA: sempre que um familiar de Raziel morre, ele rastreia e mata não só o responsável como a maioria das pessoas relacionadas a ele; se isso acontecer na frente dele, entra em Fúria Sanguinária (usa a ficha 'O Verdadeiro Raziel'). REVIDAR E ESTRIPAR: uma vez por rodada, ao sofrer ataque corpo a corpo, revida, perdendo suas RD por 1 rodada. ABRAÇO SANGUINOLENTO: acertando as garras, pode agarrar (teste 4O+15) e morder um agarrado como ação livre, causando 6d6 de dano de Sangue (Fortitude DT 23 reduz à metade) e recuperando PV igual à metade do dano. ENDURECER SANGUE: recebe RD 5 até o fim da cena. FAZER SANGRAR: 6d6 de dano de Sangue e sangramento a um alvo em alcance curto (Fortitude DT 23 reduz à metade e evita; sangramento causa 2d6 PV em vez de 1d6). MALDIÇÃO SANGUÍNEA: –O em todos os testes de um alvo em alcance curto até o fim da cena (Fortitude DT 23 reduz para 1 rodada).", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Sabara", vd = "100", elemento = "Sangue", defesa = 25, pv = 200, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 3, "int" to 2, "pre" to 2, "vig" to 2), ataques = "TESTE 3O+15, crítico 18/x3 | DANO 2d6+10 corte mais 2d4 Sangue (Espada e Adaga, corpo a corpo x2); TESTE 3O+15, crítico 19 | DANO 4d4+10 perfuração (Arremessar Faca, distância curto x2)", detalhes = "ESQUIVA: uma vez por rodada, ao sofrer um ataque, recebe +10 na Defesa contra ele. MIL PERFURAÇÕES: acertando os dois ataques de espada e adaga no mesmo alvo, também o deixa sangrando (Fortitude DT 21 evita; sangramento causa 2d6 PV em vez de 1d6). RIPOSTAR E REVIDAR: uma vez por rodada, ao sofrer ataque corpo a corpo, pode se defender atacando; vencendo o teste oposto, não sofre dano e causa 2d6+10 de corte mais 2d4 de Sangue. RINGEN AM SCHWERT: acertando um ataque, pode agarrar (teste 3O+15) e morder o agarrado como ação livre, causando 6d6 de dano de Sangue (Fortitude DT 21 reduz à metade) e recuperando metade do dano em PV. DANÇA ARMADA: gira golpeando todos os adjacentes, 2d6+10 de corte mais 2d4 de Sangue (Reflexos DT 21 reduz à metade). GOLPE DERRUBANTE: golpeia um adjacente, 2d6+10 de corte mais 2d4 de Sangue, derrubando-o (Reflexos DT 21 reduz à metade e evita); pode então reagir à ação seguinte da vítima.", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Stryzga", vd = "120", elemento = "Sangue/Morte", defesa = 30, pv = 240, deslocamento = 12, atributos = mapOf("agi" to 3, "for" to 2, "int" to 3, "pre" to 4, "vig" to 2), ataques = "TESTE 3O+15 | DANO 4d10+10 corte (Mordida e Garras, corpo a corpo x2)", detalhes = "ABSORVER ESSÊNCIA: alimentando-se de um alvo três vezes ou mais, ganha +O em testes contra ele. DOIS CORAÇÕES: ao matar alguém, inicia uma maldição — se a stryzga não for morta e queimada em 1d4+3 dias, uma nova surge na sepultura mais próxima da vítima. ECOS DE ESSÊNCIA: conhece fragmentos do inconsciente de quem já se alimentou (nomes, personalidade, trejeitos); ganha +O em testes contra seres relacionados a essas pessoas. ALIMENTAR-SE: ao acertar mordida e garras, se alimenta de parte do alvo. CONSTRIÇÃO / QUEBRA-OSSOS: podendo agarrar (teste 3O+15) um alvo Médio ou menor, e voando com ele agarrado, uma vez por rodada usa uma das duas: constrição (mais 4d10+10 de corte, Fortitude DT 23 reduz à metade) ou quebra-ossos (joga o alvo da altura desejada, dano de queda +4d6); não pode usar as duas na mesma rodada. RASANTE SILENCIOSO: atingindo um alvo desprevenido relacionado a uma essência já absorvida, causa mais 4d6 de dano mental e deixa apavorado até o fim da cena (Vontade DT 23 reduz o dano à metade e a condição para abalado). IMITAR VOZ: imita a voz de alguém de quem já se alimentou contra um alvo em alcance curto, causando 4d6 de dano mental (Vontade DT 23 reduz à metade).", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Velisar", vd = "100", elemento = "Sangue", defesa = 25, pv = 180, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 1, "int" to 4, "pre" to 3, "vig" to 2), ataques = "TESTE 3O+15, crítico 19 | DANO 2d10+10 perfuração (Garras, corpo a corpo x2)", detalhes = "VELISAR SABE: percebe auras paranormais e criaturas invisíveis ou similares em alcance médio, e percebe qualquer ameaça ou armadilha num raio de 18m. ESQUIVA: uma vez por rodada, ao sofrer um ataque, recebe +5 na Defesa contra ele. ABRAÇO SANGUINOLENTO: acertando as garras, pode agarrar (teste 3O+15) e morder o agarrado como ação livre, causando 6d6 de dano de Sangue (Fortitude DT 21 reduz à metade) e recuperando metade do dano em PV. ARMADILHA SANGUINÁRIA: cria em alcance médio uma entre três armadilhas (Investigação DT 21 para encontrar, Ocultismo DT 21 para desarmar) — Caixão de Sangue (agarra, derruba e enreda quem se aproximar a 3m; Reflexos DT 21 evita; pode teletransportar a vítima presa), Explosão de Carne (6d6 de perfuração e sangramento a 3m; Reflexos DT 21 reduz à metade e evita) ou Gás Paralisante (paralisa por 1d4+1 rodadas a 3m; Fortitude DT 21 reduz a 1 rodada). COMANDAR EXPERIMENTO: uma vez por rodada, comanda um experimento em alcance longo, dando-lhe +O em um teste se cumprir a ordem a tempo. OLHAR DA CURIOSIDADE MÓRBIDA: tenta fascinar um alvo em alcance médio (Reflexos DT 21 para desviar o olhar ou Vontade DT 21 para resistir); fascinado, só age de forma prestativa com Velisar até a condição ser removida.", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Zéfero", vd = "80", elemento = "Sangue", defesa = 23, pv = 140, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 3, "int" to 0, "pre" to 2, "vig" to 2), ataques = "TESTE 3O+10, crítico 19 | DANO 3d12+20 Sangue (Mordida Furiosa, corpo a corpo); TESTE 3O+10, crítico 19 | DANO 1d10+10 perfuração (Garras, corpo a corpo x2)", detalhes = "DEMÔNIO DE COLEIRA: domesticado por Velisar, obedece-o em troca de carne ou sangue; se Velisar morrer, pode ser domesticado por outro dono nas mesmas condições, com teste de Adestramento DT 20. FOME BESTIAL: se Velisar estiver ameaçado, gasta todas as ações para matar quem o ameaça; senão, foca no alvo com menos PV na cena. BLOQUEIO: uma vez por rodada, ao sofrer um ataque, recebe RD 10 contra ele. AGARRÃO LACERADOR: acertando a mordida, pode agarrar (teste 3O+10) e morder o agarrado como ação livre, causando 4d6 de dano de Sangue (Fortitude DT 20 reduz à metade) e recuperando metade do dano em PV. DILACERAR: acertando os dois ataques de garras no mesmo alvo, causa +1d10 de dano de perfuração adicional.", pagina = 0, fonte = "Arquivos Secretos"),
    AmeacaPronta(nome = "Aberração de Carne", vd = "40", elemento = "Sangue", defesa = 19, pv = 70, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 3, "int" to 0, "pre" to 1, "vig" to 3), ataques = "TESTE 3O+10 | DANO 2d6+6 impacto (Pancada, corpo a corpo x2)", detalhes = "AGARRÃO: se acertar um ataque de pancada, pode tentar agarrar o alvo (teste 3O+12); mantém até dois personagens agarrados por vez. ABOCANHAR: leva até dois personagens agarrados para dentro de sua boca central; ao ser abocanhado, e no início de cada turno da aberração em que continuar agarrado, o personagem sofre 3d6 pontos de dano de perfuração (Fortitude DT 15 reduz à metade); um personagem adjacente pode gastar uma ação padrão e um teste de Atletismo (DT 20) para tentar tirar outro personagem de dentro da boca.", pagina = 183, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Aniquilação", vd = "380", elemento = "Morte", defesa = 58, pv = 1200, deslocamento = 15, atributos = mapOf("agi" to 4, "for" to 5, "int" to 3, "pre" to 4, "vig" to 5), ataques = "TESTE 5O+40 | DANO 4d10+30 Sangue (Garras, corpo a corpo x2); TESTE 5O+40 | DANO 2d12+30 Sangue (Tentáculos Espinhentos, corpo a corpo x2); TESTE 4O+40 | DANO 2d10+20 Sangue (Disparo de Espinhos, distância x3, médio)", detalhes = "AGARRÃO: se acertar um ataque de tentáculos espinhentos, pode tentar agarrar o alvo (teste 5O+50); mantém até quatro personagens agarrados por vez. INSTINTO ANIQUILADOR: sempre que um personagem em alcance curto se movimenta mais de 3m, a Aniquilação faz um ataque de tentáculos espinhentos contra ele. APERTAR E DESTRUIR: no início do turno, aperta os agarrados, causando 40 pontos de dano de Sangue. BATER AS ASAS: som ensurdecedor que causa 8d6 de dano mental, empurra 6m e atordoa por 1 rodada (Fortitude DT 40 reduz o dano à metade e evita os efeitos) em todos no alcance longo. ESTRANGULAMENTO FINAL: desloca-se 15m agarrando e asfixiando quem ficar adjacente (Reflexos DT 30 evita); um agarrado pode se soltar com ação padrão e teste de Reflexos DT 30. TEMPESTADE DE ESPINHOS: uma vez por cena, causa 20d6+20 de dano de Sangue a todos em alcance médio (Reflexos DT 40 reduz à metade); perde a habilidade Disparo de Espinhos até o fim da cena. Enigma de Medo desconhecido; quando resolvido, perde resistência a dano e a Tempestade de Espinhos.", pagina = 186, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Carente", vd = "300", elemento = "Sangue / Morte", defesa = 40, pv = 700, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 4, "int" to 2, "pre" to 3, "vig" to 4), ataques = "TESTE 4O+35 | DANO 2d8+20 Sangue (Garras de Sangue, corpo a corpo x2); TESTE 4O+35 | DANO 2d12+20 Sangue (Ferrão de Sangue, corpo a corpo); TESTE 4O+35 | DANO 2d8+20 Sangue (Tentáculo, corpo a corpo)", detalhes = "REGENERAÇÃO DE SANGUE: possui Cura Acelerada 20; se ficar inconsciente ou sofrer dano de Energia, perde a habilidade até o fim da cena. MOVIMENTO FORMA INFANTIL: contorce-se de volta ao corpo da pequena criança para passar por espaços pequenos; não consegue abrir a primeira porta para entrar em um lugar, mas uma vez que a porta é aberta e sai da forma infantil, ignora essa restrição. REAÇÃO RASTEIRA DE TENTÁCULO: uma vez por rodada, ao ficar adjacente a dois ou mais seres, ataca um deles com o tentáculo; se acertar, a vítima cai e é empurrada 6m para longe. LIVRE SUGADA MORTAL: usando o ferrão, suga fluidos e apodrece órgãos internos; o alvo atingido pelo ferrão fica debilitado e enjoado até o fim da cena (Fortitude DT 35 evita). CARÊNCIA: quem já esteve envolvido na gestação de outro ser recebe +O em ataques contra o carente, mas o carente também recebe +O em ataques contra esse ser. MOVIMENTO VOCÊ É MINHA MAMÃE?: usa a forma infantil para abraçar um ser adjacente, que fica paralisado até se soltar (Reflexos DT 25 evita); pode manter o abraço indefinidamente, mas solta o alvo se sofrer dano de Energia.", pagina = 188, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Dama de Sangue", vd = "60", elemento = "Sangue", defesa = 20, pv = 105, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 3, "int" to 1, "pre" to 2, "vig" to 2), ataques = "TESTE 3O+10 | DANO 2d6+5 impacto (Tentáculo, corpo a corpo x2)", detalhes = "CONSUMIR: ao ser invocada não possui as habilidades das flores; a cada corpo consumido (ação padrão, adjacente ao cadáver) ganha uma habilidade na ordem da ficha; sem sete corpos consumidos, usa suas ações para se deslocar até um corpo e consumi-lo. Flores (cada uma pode murchar sob uma condição específica, fazendo a dama perder a habilidade e sofrer uma penalidade): ARREMESSAR (Rosa) — ergue e arremessa um alvo em alcance curto, causando 2d6 de dano de impacto e deixando-o caído (Reflexos DT 15 evita). CHUVA DE ÁCIDO (Vermelha) — 4d4 de dano químico em alcance curto (Fortitude DT 15 reduz à metade). ESPINHOS (Amarela) — 2d8 de dano de perfuração em até três alvos em alcance médio (Reflexos DT 15 reduz à metade). GRITO DEVASTADOR (Roxa) — confunde todos em alcance curto (Vontade DT 15 evita). MIASMA FÉTIDO (Azul) — enjoa por 1d4+1 rodadas em alcance curto (Fortitude DT 15 reduz a 1 rodada). PRISÃO DE TENTÁCULOS (Verde) — agarra um alvo em alcance curto até os tentáculos (20 PV) serem destruídos. VISÃO MACABRA (Laranja) — 1d6 de dano mental em alcance médio (Vontade DT 15 reduz à metade).", pagina = 191, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Enpap-X", vd = "180", elemento = "Sangue", defesa = 36, pv = 360, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 4, "int" to 1, "pre" to 2, "vig" to 3), ataques = "TESTE 4O+20 | DANO 2d10+10 impacto (Socão, corpo a corpo x4); TESTE 2O+15 | DANO 2d8+10 impacto (Correntes, distância x3, curto)", detalhes = "TRANSFORMAÇÃO: começa o combate como um existido comum (ficha própria); ao ser reduzido a 0 PV, transforma-se nesta ficha, recuperando todos os 360 PV. ACORRENTAR: acertando um ataque de correntes, pode agarrar à distância (teste 2O+17); estrangula cada agarrado no início do turno, causando 4d6 de dano de impacto; mantém até dois agarrados. FORMA DESENCADEADA: em acerto crítico com socão ou corrente, pode derrubar o alvo ou empurrá-lo 3m. CRESCER: a cada socão acertado, ganha bônus cumulativo de +1d6 de dano nas próximas rolagens até o fim do turno. MARCAS DO TERROR: faz suas marcas brilharem, causando 4d6 de dano mental a todos em alcance curto (Vontade DT 25 reduz à metade); quem resiste fica imune até o fim da cena.", pagina = 193, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Kerberos", vd = "340", elemento = "Sangue", defesa = 46, pv = 1150, deslocamento = 18, atributos = mapOf("agi" to 4, "for" to 5, "int" to 0, "pre" to 3, "vig" to 5), ataques = "TESTE 5O+40 | DANO 4d12+30 Sangue TESTE 4O+35 | DANO 4d8+20 Sangue", detalhes = "LIVRE DEVORAR: uma vez por cena, quando reduz os PV de um personagem a 0 com sua mordida, pode devorá-lo, matando-o instantaneamente e recuperando PV iguais à metade dos PV totais da vítima (Fortitude DT 40 evita). COMPLETA DERRUBAR E DEVORAR: usa a manobra derrubar em um personagem a até 3m (teste 5O+45); vencendo, desfere três ataques de mordida contra o alvo, com dano aumentado para 4d12+40. ATAQUE FLEXÍVEL: movido por sede de Sangue e desejo de matar, pode executar até quatro ataques por rodada combinando corpo a corpo e à distância, nunca repetindo o mesmo ataque mais de três vezes na mesma rodada.", pagina = 194, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Minotauro", vd = "280", elemento = "Sangue / Morte", defesa = 44, pv = 750, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 5, "int" to 1, "pre" to 3, "vig" to 5), ataques = "TESTE 5O+30 | DANO 6d12+20 perfuração (Chifres, corpo a corpo); TESTE 5O+32 | DANO 4d12+20 corte (Machado, corpo a corpo x2)", detalhes = "LIVRE CRAVAR CHIFRES: se fizer uma investida com os chifres e acertar, crava-os no alvo, que fica agarrado; enquanto mantém alguém agarrado dessa forma, não pode atacar com os chifres, mas no final de cada turno em que a vítima continuar agarrada pelos chifres, ela sofre 4d12+20 pontos de dano de Sangue.", pagina = 197, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Mulher Afogada", vd = "140", elemento = "Sangue/Energia", defesa = 28, pv = 240, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 3, "int" to 2, "pre" to 2, "vig" to 3), ataques = "TESTE 3O+15 | DANO 4d8+8 perfuração (Mordida, corpo a corpo); TESTE 3O+15 | DANO 4d6+6 corte (Garras, corpo a corpo x2); TESTE 4O+10 | DANO 4d8+8 Sangue (Jato de Sangue, distância curto)", detalhes = "FORMA DE SANGUE: por padrão está em forma líquida, com resistência a balístico/corte/impacto/perfuração/Sangue 20, deslocamento 36m e capacidade de percorrer canos e frestas; nessa forma ganha Afogar em Sangue, Arrancar Sangue e Invadir Órgãos; perde essa forma ao ser invocada fisicamente (após seu Enigma de Medo ser desvendado). SUGAR SANGUE: devora um cadáver adjacente morto nesta cena, recuperando 40 PV. AFOGAR EM SANGUE: invade nariz e boca de um alvo em alcance curto, asfixiando-o; o alvo pode tentar Fortitude DT 24 no início de cada turno para se livrar. ARRANCAR SANGUE: ao ser retirada de um corpo que afogava, causa 6d6 de dano de Sangue e deixa a vítima fraca. INVADIR ÓRGÃOS: causa 6d6 de dano de Sangue e deixa o alvo enjoado.", pagina = 199, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Titã de Sangue", vd = "220", elemento = "Sangue / Morte", defesa = 35, pv = 550, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 5, "int" to 1, "pre" to 1, "vig" to 4), ataques = "TESTE 5O+25 | DANO 4d12+10 perfuração (Mordida, corpo a corpo); TESTE 5O+25 | DANO 4d8+10 corte (Garras, corpo a corpo x2)", detalhes = "SEDE DE SANGUE: os ataques do titã causam +4d6 pontos de dano de Sangue em personagens que estejam machucados ou sangrando. LIVRE ESTRAÇALHAR: se o titã acertar um ser com sua mordida, ele estraçalha o alvo, que sofre 4d12+10 pontos de dano de perfuração adicional e fica sangrando até o final da cena (Reflexos DT 30 reduz o dano à metade e evita a condição).", pagina = 201, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Zumbi de Sangue", vd = "20", elemento = "Sangue / Morte", defesa = 17, pv = 45, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 2, "int" to 0, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+5 | DANO 1d6+5 corte (Garras, corpo a corpo x2)", detalhes = "Zumbis de Sangue são cegos e detectam presenças pela movimentação da corrente de ar, já que sua pele exposta é extremamente sensível. Comportam-se de maneira bestial e agressiva, como feras descontroladas movidas apenas por um frenesi obsessivo de devorar carne, sem raciocinar estrategicamente.", pagina = 202, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Zumbi de Sangue Bestial", vd = "100", elemento = "Sangue / Morte", defesa = 23, pv = 200, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 3, "int" to 0, "pre" to 2, "vig" to 3), ataques = "TESTE 3O+15 | DANO 2d10+5 perfuração (Mordida de Sangue, corpo a corpo); TESTE 3O+15 | DANO 2d6+5 corte (Garras de Sangue, corpo a corpo x2)", detalhes = "FURTIVO E LETAL: ao atacar um personagem desprevenido, recebe +O nos testes de ataque e, se acertar, cada ataque causa dois dados de dano adicional do mesmo tipo. INSTINTO PREDATÓRIO: não sofre penalidade em Furtividade por se mover seu deslocamento normal, agindo com instintos predatórios e emboscando alvos desprevenidos.", pagina = 203, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "O Diabo", vd = "400", elemento = "Sangue / Morte", defesa = 66, pv = 1666, deslocamento = 18, atributos = mapOf("agi" to 6, "for" to 6, "int" to 6, "pre" to 6, "vig" to 6), ataques = "TESTE 6O+45, crítico x3 | DANO 2d10+50 Sangue (Arma Sangrenta, corpo a corpo x2); TESTE 6O+45, crítico x3 | DANO 2d8+50 Sangue (Chifre do Diabo, corpo a corpo); TESTE 6O+45, crítico x3 | DANO 2d10+50 Sangue (Arma Sangrenta, distância médio x2)", detalhes = "POTÊNCIA DE SANGUE: recupera 50 PV no início de cada turno; modificador +35 em testes baseados em Força, Vigor ou Presença, e +25 nos demais. LIVRE EXPLODIR EM SANGUE: controla o sangue de qualquer ser com o qual tenha contato direto; se causar dano com a arma sangrenta ou tocar uma ferida, causa 10d6 de dano de Sangue adicional, podendo usar duas vezes por turno. LIVRE SANGRAR: acertando o chifre, pode deixá-lo preso no alvo, que recebe vulnerabilidade a Sangue até removê-lo (ação padrão, 8d8 de dano de Sangue); o chifre sempre cresce de volta no início do turno do Diabo. MOVIMENTO TRANSPORTAR PELO SANGUE: pode se deslocar através do Sangue, inclusive o que sai de um personagem, para qualquer espaço com grande quantidade de sangue exposto ou adjacente a um personagem machucado ou morrendo. PADRÃO SENHOR DO SANGUE: uma vez por cena, invoca e controla criaturas de Sangue com VD total até 400, que agem a partir da rodada seguinte. PADRÃO PACTO: oferece um pacto de Sangue; se aceito, cumpre o prometido de forma distorcida, causando 10d6 de dano mental ao alvo, que se torna servo obcecado caso enlouqueça. COMPLETA DESEJOS DE SANGUE: todos em alcance médio entram em fúria e atacam um alvo à escolha do Diabo em alcance curto (Vontade DT 45 evita); afetados usam a ação de maior dano e não podem conjurar rituais. ARDILOSO: pode escolher não ativar sua Presença Perturbadora ao encontrar uma pessoa normal.", pagina = 206, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Aracnasita", vd = "80", elemento = "Morte / Energia", defesa = 23, pv = 140, deslocamento = 12, atributos = mapOf("agi" to 3, "for" to 2, "int" to 1, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+15 | DANO 2d10+10 perfuração (Mordida, corpo a corpo)", detalhes = "PERCEPÇÃO TÁTIL: percebe tudo que toca sua teia, ignorando penalidades de visão ou de sentidos para objetos e seres em contato com ela. LIVRE ESTACAR: ao causar dano com a mordida, usa o Lodo da Morte para prender o alvo no lugar, causando +1d10 de dano de Morte e deixando-o agarrado; solta-se com ação padrão e Atletismo DT 20 (adjacentes podem ajudar ou tentar soltá-la com o mesmo teste). REAÇÃO DESOVAR ARANHAS: uma vez por cena, ao ficar machucada, desova aranhas menores; no 1º turno seguinte, quem iniciar o turno em alcance curto sofre 2d6 de dano mental (Vontade DT 15 reduz à metade); no 2º turno, sofre também 2d8 de dano de Morte (Fortitude DT 15 reduz à metade); no 3º turno, os efeitos passam a valer em alcance médio; a partir do 4º turno, quem morrer em alcance médio é consumido e vira uma nova aracnasita com 70 PV, sem a habilidade Desovar Aranhas. MOVIMENTO DISPARAR TEIA: dispara uma teia em alcance curto que ocupa uma área de 3m de lado; quem estiver ou entrar nela fica agarrado (Reflexos DT 20 evita); a teia é tomada pelo Lodo da Morte e causa 2d8+10 de dano de Morte a cada turno que o personagem inicie agarrado; escapa causando 15 de dano de corte à teia ou com Atletismo DT 20 (ação padrão); a teia dura até o fim da cena.", pagina = 209, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Carniçal Preto da Morte", vd = "200", elemento = "Morte", defesa = 38, pv = 400, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 4, "int" to 3, "pre" to 3, "vig" to 3), ataques = "TESTE 4O+25 | DANO 4d10+20 Morte (Garra da Morte, corpo a corpo x2)", detalhes = "PANCADA PODEROSA: em acerto crítico com a garra, pode empurrar o alvo 6m; colisão com objeto resistente causa 4d6 de dano de impacto (a ele e ao objeto/ser atingido). COMANDO: dá uma ordem a um ser em alcance curto (Vontade DT 29 evita), gerando um efeito do ritual Perturbação. HIPNOSE: domina a mente de um ser em alcance curto (Vontade DT 29 evita), que obedece exceto tirar a própria vida; pode repetir o teste a cada turno com bônus cumulativo de +1; mantém até três hipnotizados por vez; contra um alvo enlouquecendo, o domínio é permanente até o carniçal ser destruído. REANIMAR CORPOS: uma vez por cena, reanima 2d4+2 corpos em alcance médio como esqueletos de Lodo, que atacam o ser mais próximo até serem destruídos. CORPO FECHADO: é imune a dano balístico, exceto para quem mirar na cabeça.", pagina = 211, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Esqueleto de Lodo", vd = "20", elemento = "Morte", defesa = 14, pv = 40, deslocamento = 6, atributos = mapOf("agi" to 2, "for" to 2, "int" to 0, "pre" to 1, "vig" to 1), ataques = "TESTE 2O+5 | DANO 2d6+2 corte (Garras, corpo a corpo x2)", detalhes = "IMORTALIDADE: ao morrer, desfaz-se em uma poça de Lodo e ossos, retornando após 1d3 rodadas com 20 PV; dano de fogo ou Energia enquanto está na forma de poça o destrói permanentemente. ESPIRAL DE LODO: transforma-se em uma poça de Lodo e se lança em espiral por até 9m em linha reta; qualquer ser no caminho sofre 2d10 de dano de Morte (Reflexos DT 14 reduz à metade); depois se reforma no fim do trajeto.", pagina = 211, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Ceifador Espiral", vd = "380", elemento = "Morte", defesa = 58, pv = 999, deslocamento = 15, atributos = mapOf("agi" to 5, "for" to 5, "int" to 5, "pre" to 5, "vig" to 5), ataques = "TESTE 5O+40 | DANO 5d10+20 Morte (Foice da Morte, corpo a corpo x2)", detalhes = "DECEPAR: em acerto crítico com a foice, o alvo é reduzido a 25 PV e perde 1 ponto de Força, Agilidade ou Vigor permanentemente (aleatório); com 25 PV ou menos, morre de imediato; ao matar um ser, o Ceifador recebe 50 PV temporários e seus ataques de foice ganham +1d10 de dano até o fim da cena. TRANSPORTE PELO PÓ: dentro da área de Cinzas das Terras Desoladas, pode se teletransportar para outro espaço da área como ação de movimento e atacar como ação livre. CONTEMPLAR A ESPIRAL: causa 10d10+30 de dano mental a todos em alcance médio que o vejam (Vontade DT 43 reduz à metade); quem sofre o dano fica imune até o fim da cena. CINZAS DAS TERRAS DESOLADAS: transforma uma área de alcance longo em cinzas; cada ser dentro sofre 10d10+20 de dano de Morte e fica enjoado (Fortitude DT 43 reduz o dano à metade e evita a condição); quem termina o turno na área sofre mais 20 de dano de Morte.", pagina = 213, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Enraizado", vd = "120", elemento = "Morte / Energia", defesa = 28, pv = 140, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 3, "int" to 1, "pre" to 1, "vig" to 3), ataques = "TESTE 3O+15 | DANO 2d8+8 impacto mais 2d12 Morte (Punho Espinhento, corpo a corpo x2)", detalhes = "IMORTALIDADE: ao morrer, desfaz-se em uma poça de Lodo, galhos e raízes, retornando após 1d2 rodadas com 70 PV; se sofrer 20 pontos somados de dano de fogo ou Energia enquanto estiver na forma de poça, é permanentemente destruído. VENENO PÚTRIDO: na primeira vez que um personagem sofre dano do punho espinhento em uma cena, fica envenenado; no início de cada turno seguinte, faz Fortitude DT 23 — se falhar, sofre 4d12 de dano de Morte; se passar, cura-se do veneno.", pagina = 214, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Escutado", vd = "160", elemento = "Morte / Energia", defesa = 29, pv = 290, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 3, "int" to 1, "pre" to 2, "vig" to 3), ataques = "TESTE 3O+20 | DANO 3d6+10 perfuração (Mordida, corpo a corpo x2); TESTE 4O+15 | DANO 1d10+10 impacto (Cabeça Arremessada, distância curto x2)", detalhes = "MULTIPLICAÇÃO MELÓDICA: no início do turno, se estiver ouvindo a melodia de sua criação, manifesta uma cópia sua em alcance curto (145 PV, sem imunidade a dano), que age a partir do próximo turno do original e também pode gerar novas cópias; o escutado e suas cópias tentam eliminar quem estiver tocando a melodia. MOVIMENTO VOMITAR LODO: uma vez por cena, na primeira rodada após ser manifestada, cada cópia despeja um jorro de Lodo em um ser em alcance curto, causando 4d10+10 de dano de Morte e deixando-o lento até o fim da cena (Reflexos DT 25 reduz o dano à metade e evita a condição).", pagina = 216, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Marionete", vd = "280", elemento = "Morte", defesa = 40, pv = 700, deslocamento = 6, atributos = mapOf("agi" to 3, "for" to 5, "int" to 1, "pre" to 5, "vig" to 2), ataques = "TESTE 5O+30 | DANO 10d8+10 Morte (Foice Óssea, corpo a corpo x2)", detalhes = "MOMENTO PASSIVO: não pode ter seu deslocamento reduzido, ignora terreno difícil e não sofre dano ou efeitos que dependam de tocar o chão. REAÇÃO REFLEXOS GUIADOS POR CORDA: uma vez por rodada, quando um ser fica adjacente a ela, pode fazer um ataque de foice óssea contra ele. COMPLETA IRONIA DO DESTINO: faz dois ataques de foice óssea contra um ser adjacente; se o segundo acertar, agarra a vítima com a arma e pode se deslocar 6m carregando-a; enquanto estiver agarrando, divide com o alvo qualquer dano que sofrer.", pagina = 219, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Múmia Xipófaga", vd = "240", elemento = "Morte", defesa = 35, pv = 400, deslocamento = 9, atributos = mapOf("agi" to 5, "for" to 4, "int" to 2, "pre" to 3, "vig" to 4), ataques = "TESTE 4O+30 | DANO 4d8+30 corte (Garra Enfaixada, corpo a corpo x2); TESTE 5O+25 | DANO 3d6+30 Morte mais 3d8 mental (Vomitar Lodo, distância x2, curto)", detalhes = "FAIXAS DA PERMANÊNCIA: ao ser reduzida a 0 PV não é destruída, podendo agir até o fim do próximo turno; se não terminar esse turno com ao menos 1 PV, morre. AGARRADA MUMIFICADORA: acertando a garra enfaixada pode agarrar o alvo (teste 4O+30); o agarrado sofre 4d8+30 de dano de Morte no início de cada turno enquanto a múmia recupera a mesma quantidade de PV; se reduzido a 0 PV assim, o alvo se torna um esqueleto de Lodo. AMALGAMAR: com 0 PV, pode se fundir a um ser morto ou criatura de Morte adjacente, recuperando 200 PV, passando a atacar mais uma vez com as garras e causando +5 de dano por ataque; pode se amalgamar uma segunda vez (recupera mais 200 PV, ataca quatro vezes, bônus total +10 por ataque).", pagina = 221, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Nidere", vd = "320", elemento = "Sangue / Morte", defesa = 50, pv = 800, deslocamento = 24, atributos = mapOf("agi" to 5, "for" to 5, "int" to 3, "pre" to 4, "vig" to 5), ataques = "TESTE 5O+35 | DANO 4d10+40 Morte (Garra Invertida, corpo a corpo x2); TESTE 5O+35 | DANO 4d12+40 Morte (Mordida Invertida, corpo a corpo)", detalhes = "CAÇADOR VELOZ: pode se mover em seu deslocamento normal sem penalidade em Furtividade. REGENERAÇÃO ACELERADA: possui Cura Acelerada 50; perde essa habilidade se seu Enigma de Medo for resolvido. SENSO DE DIREÇÃO PERFEITO: nunca se perde e recebe +OO em Percepção e Sobrevivência (já contabilizados na ficha); perde a habilidade caso o Enigma de Medo seja resolvido. LIVRE REVERTER: um ser que sofra dano das garras invertidas é afetado por um surto temporal que apodrece a carne, ficando enjoado até o final do próximo turno. LIVRE RASTREAR E ABATER: causa +6d6 de dano contra seres desprevenidos.", pagina = 224, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Sempiternal", vd = "360", elemento = "Morte / Energia", defesa = 53, pv = 990, deslocamento = 12, atributos = mapOf("agi" to 5, "for" to 5, "int" to 4, "pre" to 5, "vig" to 4), ataques = "TESTE 5O+40 | DANO 4d10 Morte mais envelhecimento (Dedos Alongados, corpo a corpo x4)", detalhes = "TOQUE ACELERADOR: sempre que um ser sofre dano dos dedos alongados, envelhece 1d10 anos; envelhecendo 20 anos ou mais, fica fraco até o fim da cena; 40 anos ou mais, fica debilitado até o fim da cena; 60 anos ou mais, morre (seres com afinidade a Morte são imunes). MOVIMENTO CORRENTES DE LODO: projeta vinhas de Lodo pelo chão, ocupando toda uma área em alcance médio; todos na área sofrem 20d6 de dano de Morte (Fortitude DT 40 reduz à metade); quem fica machucado por esse dano é infectado pelo Lodo e recebe vulnerabilidade a Morte até o fim da cena; quem é reduzido a 0 PV se torna um enraizado.", pagina = 226, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Succ", vd = "40", elemento = "Morte / Energia", defesa = 20, pv = 65, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 2, "int" to 0, "pre" to 1, "vig" to 1), ataques = "TESTE 4O+10 | DANO 2d8+2 perfuração (Mordida, corpo a corpo)", detalhes = "LIVRE SUCÇÃO: se acertar a mordida, prende os dentes no rosto da vítima e tira o ar de seus pulmões; a vítima faz Fortitude DT 17 — se passar, solta-se; se falhar, fica inconsciente e no início do próximo turno do succ é reduzida a 0 PV e fica morrendo. Enquanto prende alguém dessa forma, o succ só pode usar reações e seu deslocamento é reduzido para 3m; se sofrer 10 ou mais pontos de dano na mesma rodada, solta a vítima.", pagina = 227, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "O Deus da Morte", vd = "400", elemento = "Morte / Conhecimento", defesa = 60, pv = 2000, deslocamento = 15, atributos = mapOf("agi" to 6, "for" to 6, "int" to 5, "pre" to 5, "vig" to 7), ataques = "TESTE 6O+45 | DANO 5d10+50 Morte (Soco Espiral, corpo a corpo x2)", detalhes = "POTÊNCIA DE MORTE: modificador +35 em testes baseados em Força, Vigor ou Presença, e +25 nos demais. SENHOR DO TEMPO: no início de cada rodada, rola 1d20 e recebe um turno adicional na contagem de iniciativa correspondente ao resultado. CICLO INFINITO: recupera 50 PV no início de cada turno; ao ser reduzido a 0 PV, vira uma poça de Lodo e se manifesta no cadáver mais próximo (ou de maior NEX) no início do turno seguinte, recuperando todos os PV e curando todas as condições — perde essa regeneração se o Enigma de Medo for resolvido. LIVRE AGARRÃO: acertando o soco espiral em um ser Médio ou menor, pode agarrar (teste 6O+47). LIVRE CONTROLAR RELÓGIO INTERNO: no início de cada turno, encerra até duas condições que o afetem. MOVIMENTO CONTROLAR MORTOS: controla qualquer criatura de Morte em alcance longo, fazendo-a se mover e atacar. MOVIMENTO ESPIRAL DESCENDENTE: acelera o tempo de um ser agarrado, que fica paralisado sentindo cada segundo passar e envelhece 3d20 anos, sofrendo 1 de dano mental por ano envelhecido. DESTRUIR O DIABO: é a única coisa capaz de resolver o Enigma de Medo do Diabo. PADRÃO ESPIRAL DESTRUTIVA: cria uma espiral de Morte com 12m de raio em alcance longo; todos na área sofrem 10d10+50 de dano de Morte (Fortitude DT 45 reduz à metade).", pagina = 230, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anjo", vd = "380", elemento = "Sangue / Conhecimento", defesa = 57, pv = 1111, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 5, "int" to 5, "pre" to 5, "vig" to 5), ataques = "TESTE 5O+40 | DANO 4d10+40 Conhecimento (Asas do Conhecimento, corpo a corpo x2); TESTE 4O+40 | DANO 6d8+20 Conhecimento (Olhares do Saber, distância longo x2)", detalhes = "JULGAMENTO: sempre que um ser sofre dano de Conhecimento das asas ou dos olhares do saber, sofre também dano mental igual à metade do dano de Conhecimento (após resistências); um ser reduzido a Sanidade 0 dessa forma inexiste, morrendo instantaneamente. LIVRE FAIXAS DETENTORAS: acertando as asas do Conhecimento em um ser Médio ou menor, pode agarrar (teste 5O+45) — o agarrado também fica fascinado; mantém um ser agarrado por vez, sem impedir o uso das asas. PADRÃO CHAMAS REVELADORAS: manifesta um círculo de chamas douradas que se expande em alcance médio; todos na área sofrem 10d8 de dano de Conhecimento (Vontade DT 43 reduz à metade) e ganham uma auréola reveladora — até o fim da cena, o anjo sabe onde estão todos com auréola, ignorando furtividade e invisibilidade. COMPLETA RAIO DOURADO: uma vez por cena, dispara um raio dourado numa linha de 3m em alcance longo, causando 15d8+50 de dano de Conhecimento (Reflexos DT 43 reduz à metade).", pagina = 234, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Bicho-Papão", vd = "300", elemento = "Conhecimento / Medo", defesa = 41, pv = 750, deslocamento = 15, atributos = mapOf("agi" to 5, "for" to 4, "int" to 3, "pre" to 5, "vig" to 4), ataques = "TESTE 5O+35 | DANO 4d10+10 Conhecimento (Garras Atormentadoras, corpo a corpo x3)", detalhes = "TAMANHO ADAPTÁVEL: consegue se esconder em locais menores reduzindo seu tamanho de forma paranormal; seu deslocamento não é reduzido por andar furtivamente ou escalar. TORMENTO INFANTIL: fica desprevenido se estiver ouvindo cantiga de ninar ou canção infantil; ao ouvir choro de criança, usa todas as ações para encontrar e silenciar a fonte. DESTRUIR MENTE: sempre que acerta um alvo perturbado com as garras, causa também 1d8 de dano mental por acerto. MOVIMENTO ATORMENTAR: envia sussurros a um ser em alcance curto, causando 3d8 de dano mental (Vontade DT 30 reduz à metade); se estiver escondido do alvo, o dano aumenta em +3d8. COMPLETA SALTAR E ASSUSTAR: se estiver escondido de um ser em alcance curto, sai do esconderijo assumindo forma assustadora; o alvo sofre 10d8 de dano mental (Vontade DT 35 reduz à metade).", pagina = 237, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Espreitador", vd = "220", elemento = "Conhecimento / Medo", defesa = 34, pv = 500, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 2, "int" to 3, "pre" to 3, "vig" to 2), ataques = "TESTE 2O+10 | DANO 1d6+2 impacto (Pancada, corpo a corpo x2)", detalhes = "MOVIMENTO CORRER PELAS FRESTAS: teletransporta-se para qualquer espaço em alcance longo, desde que exista uma fresta no caminho (espaço Pequeno ou menor totalmente delimitado, como uma porta entreaberta ou um buraco na parede). COMPLETA ESPREITAR: uma vez por cena, se adjacente a um ser dormindo, causa 10d6 de dano mental (Vontade DT 30 reduz à metade); se a vítima ficar enlouquecendo por esse dano, pode criar uma cópia observada dela. PADRÃO CÓPIA OBSERVADA: manifesta uma cópia de um ser deixado enlouquecendo pela habilidade Espreitar; a cópia usa a mesma ficha, mas causa dano de Conhecimento em vez do dano normal, não pode conjurar rituais nem usar habilidades paranormais, e dura até o fim da cena.", pagina = 238, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Estrangeiro", vd = "340", elemento = "Conhecimento / Energia", defesa = 50, pv = 750, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 5, "int" to 5, "pre" to 5, "vig" to 3), ataques = "TESTE 5O+35 | DANO 4d8+10 Conhecimento (Toque Sutil, corpo a corpo x3); TESTE 5O+35 | DANO 4d10+20 Conhecimento (Rajada Psíquica, distância extremo x2)", detalhes = "LIVRE COMANDAR: sempre que causa dano com a rajada psíquica, pode tentar dominar a mente do alvo (Vontade DT 35 evita); se falhar, o alvo é forçado a atacar, render-se ou fugir no seu próximo turno (seres com Intelecto 5+ são imunes). LIVRE APAGAR MEMÓRIA: um ser que enlouqueça por seus ataques tem a mente controlada pelo Estrangeiro, ou pode ter sua memória apagada, recuperando 1d4 de Sanidade e duvidando da existência da criatura. LIVRE OBLÍVIO: quem sofre dano do toque sutil esquece momentaneamente da existência do Estrangeiro (Vontade DT 30 evita), considerando-o invisível; repete o teste no fim de cada turno — se passar, volta a percebê-lo, mas sofre 6d6 de dano mental (não se aplica a quem está incubando uma larva). COMPLETA INCUBAR: toca um ser adjacente alheio a sua presença e coloca uma larva nele; enquanto incuba, o Estrangeiro tem acesso total à mente do hospedeiro e a larva causa 1d6 de dano mental no início de cada cena; ao zerar a Sanidade do hospedeiro, um novo Estrangeiro eclode, matando-o.", pagina = 241, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Existido", vd = "20", elemento = "Sangue / Conhecimento", defesa = 13, pv = 36, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 1, "int" to 4, "pre" to 2, "vig" to 2), ataques = "TESTE O+5 | DANO 1d4+1 impacto (Pancada, corpo a corpo)", detalhes = "LIVRE BRILHO ENLOUQUECEDOR: uma vez por rodada, faz suas marcas douradas brilharem; todos em alcance médio que possam vê-lo sofrem 1d6 de dano mental (Vontade DT 14 reduz à metade). MOVIMENTO FORTALECIMENTO PARANORMAL: até o fim da cena, recebe +O em testes baseados em Agilidade, Força e Vigor e suas pancadas causam +2d4 de dano de Conhecimento; só pode usar esta habilidade se tiver causado dano mental com o Brilho Enlouquecedor nesta cena.", pagina = 242, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Lembrado", vd = "100", elemento = "Conhecimento", defesa = 22, pv = 180, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 2, "int" to 4, "pre" to 2, "vig" to 2), ataques = "TESTE 2O+5 | DANO 2d4+7 impacto (Pancada, corpo a corpo x2)", detalhes = "AURA MANIFESTADA: cercado por uma aura dourada de faces flutuantes que gritam; personagens em alcance curto sofrem –OO em todos os testes. EXPANDIR AURA: expande a aura, causando 6d6 de dano mental a todos em alcance curto (Vontade DT 20 reduz à metade). Evolução do existido quando a barreira mental de alguém com alta exposição paranormal se rompe por completo.", pagina = 242, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Ocioso", vd = "260", elemento = "Sangue / Conhecimento", defesa = 37, pv = 390, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 5, "int" to 1, "pre" to 5, "vig" to 3), ataques = "", detalhes = "SEMPRE PRESENTE: no começo de uma cena, escolhe um personagem que possa vê-lo para ser seu alvo; só esse alvo consegue enxergá-lo — para os demais, é invisível; parece deixar de existir quando o alvo está de olhos fechados. REAÇÃO RETALIAÇÃO: sempre que é atacado ou alvo de uma habilidade, teletransporta-se para ficar adjacente ao atacante e faz um ataque corpo a corpo contra ele (teste 5O+30, dano 4d10+20 de impacto não letal). LIVRE PERMANECER PRÓXIMO: uma vez por rodada, pode teletransportar-se para qualquer ponto dentro do campo de visão do alvo. COMPLETA ATERRORIZAR: o ocioso fica parado; seu olhar entra na alma do alvo, que sofre 4d10+10 de dano mental se estiver adjacente. Não ataca ativamente, mas reage a qualquer ataque, muitas vezes incapacitando o alvo sem matá-lo.", pagina = 244, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Parasita de Culpa", vd = "60", elemento = "Conhecimento", defesa = 15, pv = 90, deslocamento = 6, atributos = mapOf("agi" to 2, "for" to 0, "int" to 4, "pre" to 4, "vig" to 1), ataques = "TESTE O | DANO 1d4 impacto (Pancada, corpo a corpo)", detalhes = "DEVORAR CULPA: alimenta-se da culpa e dos traumas de um hospedeiro; ao se fixar em um ser dormindo, todos os seres dormindo em alcance médio ficam presos em um sonho compartilhado até o parasita ser derrotado ou o hospedeiro morrer/enlouquecer. FIXAR: aproxima-se de um alvo dormindo, que testa Percepção (–OO) contra a Furtividade do parasita (2O+15); se passar, desperta antes da fixação; se falhar, torna-se hospedeiro. ATORMENTAR: se fixado, atormenta a mente do hospedeiro e de todos mantidos inconscientes; no início de cada cena do sonho, todos sofrem 2d6 de dano mental (Vontade DT 20 reduz à metade). CÓPIAS DO HOSPEDEIRO: se fixado, manifesta até quatro cópias de Conhecimento do hospedeiro (20 PV cada, dano de Conhecimento); dentro do sonho usam a Presença do parasita. Enigma de Medo: identificar que estão em sonho compartilhado e qual personagem é o hospedeiro; o hospedeiro deve então confrontar e derrotar as manifestações sozinho, dentro do sonho.", pagina = 246, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Rastejador Sombrio", vd = "180", elemento = "Conhecimento/Sangue", defesa = 41, pv = 330, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 3, "int" to 3, "pre" to 3, "vig" to 3), ataques = "TESTE 4O+20 | DANO 4d8+5 Conhecimento (Toque da Dor, corpo a corpo x3)", detalhes = "VULNERABILIDADE A LUZ: exposto diretamente a luz forte que o ilumine por completo, sofre –10 em Defesa e perde Desespero, Rastejar e Tentáculos das Sombras. DESESPERO: sempre que um ser sofre dano do toque da dor, sofre também dano mental igual (Vontade DT 25 reduz o dano mental à metade). RASTEJAR: sob cobertura ou camuflagem, recebe +10 em Furtividade e não tem o deslocamento reduzido por se mover furtivamente, até o início do próximo turno. TENTÁCULOS DAS SOMBRAS: projeta fibras pelas sombras contra até três seres em alcance médio, que ficam agarrados (Reflexos DT 28 evita); pode arrastar os agarrados com uma ação de movimento; no fim de cada turno agarrado, a vítima sofre 4d6 de dano mental.", pagina = 248, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Silhueta", vd = "360", elemento = "Sangue / Conhecimento", defesa = 55, pv = 500, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 4, "int" to 5, "pre" to 5, "vig" to 4), ataques = "TESTE 4O+10 | DANO 2d6 Conhecimento", detalhes = "AURA TANGÍVEL: qualquer ser ou item que a tocar sofre 20d12 de dano de Conhecimento (Fortitude DT 42 reduz à metade) e, se reduzido a 0 PV, é instantaneamente desintegrado; um mesmo alvo só sofre esse dano uma vez por turno. CONHECIMENTO VERDADEIRO: sabe tudo, com +25 em testes baseados em Intelecto e Presença, e +20 em testes baseados em Agilidade, Força e Vigor. LIVRE REESCREVER A REALIDADE: enquanto se desloca, pode transformar objetos em alcance curto em outros objetos do mesmo tamanho; seres vivos e o que estiverem vestindo ou portando não são afetados. PADRÃO TOQUE DEVASTADOR: raramente age de forma agressiva, mas quando precisa remover algo do caminho, toca até dois seres e/ou objetos, causando o dano de sua aura tangível.", pagina = 250, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Vulto", vd = "40", elemento = "Sangue / Conhecimento", defesa = 19, pv = 60, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 2, "int" to 2, "pre" to 2, "vig" to 1), ataques = "TESTE 4O+10 | DANO 2d6 Conhecimento (Toque Macabro, corpo a corpo x2)", detalhes = "AURA TANGÍVEL: procura pessoas assustadas para se alimentar do susto; ataques contra pessoas sob efeito de qualquer condição de medo causam +2d6 de dano de Conhecimento. COMPLETA PLANTAR PARANOIA: chacoalha a Membrana para implantar medo e paranoia; cada personagem em alcance médio fica abalado (Vontade DT 15 evita), ou apavorado se já estiver abalado; se o vulto estiver escondido ao usar essa habilidade, os alvos sofrem –O no teste de Vontade.", pagina = 251, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anfitrião", vd = "400", elemento = "Conhecimento", defesa = 55, pv = 1200, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 4, "int" to 6, "pre" to 6, "vig" to 5), ataques = "", detalhes = "Também creditada nos registros como 'Máscara do Desespero': uma relíquia minúscula que só pode ser destronada por si mesma — é a única capaz de resolver o próprio Enigma de Medo do Anfitrião que a porta. POTÊNCIA DO CONHECIMENTO: modificador +35 em testes de perícia baseados em Intelecto, Presença e Vigor, e +25 nos demais atributos. CONJURAÇÃO VERDADEIRA: uma vez por turno conjura um ritual de Conhecimento de qualquer círculo, execução máxima de ação completa e custo máximo de 20 PE (DT 45). ONIPRESENÇA: desloca-se para qualquer lugar da Realidade onde haja sombra ou escuridão, independente da distância; sabe tudo que acontece na Realidade simultaneamente; ninguém pode se esconder dela, e ignora a necessidade de ver ou ouvir para usar suas habilidades. REESCREVER REALIDADE: altera propriedades de seres e objetos em alcance médio; contra objetos de até 1 tonelada muda composição, posição e estado da matéria (Reflexos DT 45 do portador evita, se vestido/empunhado); contra seres, causa 10d6 de dano de Conhecimento, 10d6 de dano mental e uma condição à escolha, exceto morrendo/enlouquecendo (Vontade DT 45 reduz cada dano à metade e evita a condição).", pagina = 254, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Máscara do Desespero", vd = "400", elemento = "Sangue / Conhecimento", defesa = 55, pv = 1200, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 4, "int" to 6, "pre" to 6, "vig" to 5), ataques = "", detalhes = "LIVRE CONJURAÇÃO VERDADEIRA: uma vez por turno, conjura um ritual de Conhecimento de qualquer círculo, de sua escolha, com execução máxima de ação completa e custo máximo de 20 PE (DT 45 para resistir). MOVIMENTO ONIPRESENÇA: desloca-se para qualquer local da Realidade onde haja sombra ou escuridão, independente da distância; sabe tudo o que acontece na Realidade simultaneamente, ninguém pode se esconder dela, e ignora a necessidade de ver ou ouvir para usar suas habilidades. PADRÃO REESCREVER REALIDADE: altera propriedades de seres e objetos em alcance médio; contra objetos de até 1 tonelada, muda composição, posição e estado da matéria (Reflexos DT 45 do portador evita, se vestido/empunhado); contra seres, causa 10d6 de dano de Conhecimento, 10d6 de dano mental e uma condição à escolha (exceto morrendo/enlouquecendo — Vontade DT 45 reduz cada dano à metade e evita a condição). DESTRONAR O ANFITRIÃO: é a única capaz de resolver o Enigma de Medo do Anfitrião. POTÊNCIA DO CONHECIMENTO: modificador +35 em testes baseados em Intelecto, Presença e Vigor, e +25 nos demais.", pagina = 254, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anárquico", vd = "20", elemento = "Conhecimento / Energia", defesa = 21, pv = 30, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 2, "int" to 0, "pre" to 0, "vig" to 1), ataques = "TESTE 2O+5 | DANO 2d12 impacto (Pancada Errática, corpo a corpo)", detalhes = "LIVRE COMPORTAMENTO ERRÁTICO: no início do turno, age de modo aleatório (1d6): 1-2, pula sobre o personagem mais próximo com investida (ou agride, se já adjacente), ou corre em sua direção; 3-4, projeta luz prismática em um ser em alcance médio, causando 2d8 de dano de Energia e atordoando por 1 rodada (Fortitude DT 14 reduz o dano à metade e evita a condição); 5, explode Energia em alcance curto, causando 2d6 de dano de Energia (Reflexos DT 14 reduz à metade; adjacentes sofrem +1d6); 6, ri descontroladamente e agride o mais próximo, ficando desprevenido até o fim do próximo turno, mas com ataques imprevisíveis que não podem ser esquivados. Se não puder agir, fica parado se contorcendo, recebendo resistência a dano 5 até o início do próximo turno.", pagina = 257, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anárquico Descontrolado", vd = "120", elemento = "Conhecimento / Energia", defesa = 28, pv = 120, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 3, "int" to 2, "pre" to 2, "vig" to 3), ataques = "TESTE 4O+15 | DANO 4d12 impacto (Pancada Energética, corpo a corpo x2)", detalhes = "LIVRE ACELERAÇÃO: sempre que um personagem sofre dano da pancada energética, entra em estado de aceleração; no próximo turno, se realizar ação de movimento + padrão, ou uma ação completa, sofre 4d12 de dano de Energia colateral. MOVIMENTO AUTODESTRUIÇÃO: concentra Energia e se autodestrói, causando 8d12 de dano de Energia em todos em alcance curto (Reflexos DT 25 reduz à metade; adjacentes sofrem –OO no teste); morre após usar essa habilidade.", pagina = 259, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anomalia", vd = "380", elemento = "Energia / Medo", defesa = 0, pv = 1000, deslocamento = 0, atributos = mapOf("agi" to 0, "for" to 0, "int" to 5, "pre" to 5, "vig" to 0), ataques = "", detalhes = "EXISTÊNCIA IMPOSSÍVEL: não se desloca normalmente — existe dentro de um objeto que possa ser aberto por uma porta; enquanto a porta estiver aberta, está manifestada e pode usar seus poderes, perseguindo quem a manifestou sempre que abrirem uma porta ou compartimento. IMATERIAL: possui corpo físico desprezível, escondido atrás de uma imensidão de Energia paranormal; é imune a dano e a todas as condições, não faz testes normais, e só pode ser derrotada resolvendo seu Enigma de Medo. LIVRE ROMPER CONSCIÊNCIA: no início do turno, sorteia um ser em sua linha de visão e tenta romper sua razão; a vítima sofre 10d6 de dano mental (Vontade DT 41 reduz à metade) e, se enlouquecer, é absorvida pela anomalia. LIVRE MANIPULAR ONDAS DA EXISTÊNCIA: no final do turno, ativa, desativa ou opera até seis objetos tecnológicos em alcance médio, ou os sobrecarrega, causando 2d12 de dano de Energia por objeto em todos na área (Reflexos DT 30 reduz à metade). COMPLETA MANIFESTAR O IMPOSSÍVEL: invoca criaturas de Energia com VD total até 240, que aparecem em alcance curto e agem a partir da próxima rodada.", pagina = 261, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Anomiático", vd = "240", elemento = "Conhecimento / Energia", defesa = 41, pv = 600, deslocamento = 18, atributos = mapOf("agi" to 5, "for" to 3, "int" to 1, "pre" to 4, "vig" to 3), ataques = "TESTE 5O+30 | DANO 4d12+20 Energia (Garra Desintegradora, corpo a corpo x2)", detalhes = "LIVRE COMPORTAMENTO ERRÁTICO: no início do turno, executa três comportamentos aleatórios (rolando 1d6 três vezes, na ordem): 1-2, salta até 18m em direção ao ser mais próximo e agride com as garras desintegradoras se ficar adjacente; 3, transforma-se em facho de Energia e se move até ficar adjacente a um alvo aleatório entre os que o enfrentam; 4, explode parcialmente, causando dano de Energia conforme a distância do alvo — 4d12+20 (médio), 6d12+20 (curto) ou 8d12+20 (adjacente), com Reflexos DT 30 reduzindo à metade para alcance médio/curto, e perde 50 PV ao usar; 5, fica desprevenido até o início do próximo turno, com ataques imprevisíveis; 6, toca um ser adjacente, que sofre 10d12+20 de dano de Energia (Fortitude DT 30 reduz à metade). Se não puder executar uma ação, fica parado se contorcendo e ganha +10 de resistência a dano até o próximo turno, por ação perdida.", pagina = 263, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Ciborgue", vd = "80", elemento = "Sangue / Conhecimento", defesa = 25, pv = 160, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 3, "int" to 2, "pre" to 2, "vig" to 3), ataques = "TESTE 3O+10, crítico 18 | DANO 1d12+10 corte (Braço Laminado, Estado Alpha, corpo a corpo x2); TESTE 3O+10 | DANO 2d8+10 impacto (Punho Energizado, Estado Beta, corpo a corpo); TESTE 3O+10 | DANO 4d12+5 Energia (Canhão, Estado Gama, distância longo); TESTE 3O+10 | DANO 1d12+5 Energia (Raio Energético, Estado Delta, distância médio)", detalhes = "REGENERAÇÃO ENERGÉTICA: recupera 20 PV no início do turno; perde a habilidade se perder três ou mais estados de combate. ESTADO DE COMBATE: no início do turno, assume um dos quatro estados de combate disponíveis — Alpha (foco em atacar inimigos próximos), Beta (perseguir e atacar à distância), Gama (ataques à distância) ou Delta (tático e defensivo); um estado deixa de estar disponível quando sua fraqueza é resolvida. COMPLETA INVESTIDA ENERGÉTICA (Beta): avança até 24m (18) e ataca com punho energizado com +O no teste; se acertar, causa +2d8 de dano (total 4d8+10) e derruba o alvo (Fortitude DT 20 evita). MOVIMENTO CRIAR BARREIRA (Delta): recebe +5 na Defesa até o início do próximo turno. MOVIMENTO REINICIAR (Delta): encerra uma condição que o esteja afetando. LIVRE DESORIENTAR (Gama): quem sofre dano do raio energético fica alquebrado, ou atordoado por uma rodada se já estiver alquebrado (Vontade DT 20 evita). ENIGMA DE MEDO: cada estado possui uma fraqueza específica; quando resolvida, o ciborgue não pode mais assumir esse estado; sem nenhum estado disponível, desativa-se (Defesa 10, deslocamento 0m).", pagina = 265, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Infecticídio", vd = "280", elemento = "Sangue / Energia", defesa = 25, pv = 600, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 5, "int" to 1, "pre" to 1, "vig" to 5), ataques = "TESTE 5O+30 | DANO 4d12+20 Energia (Pancadas Infectadas, corpo a corpo x3)", detalhes = "HORDA: sofre apenas metade do dano de ataques/habilidades que afetem um único ser, mas o dobro do dano de efeitos de área; ao errar um ataque, ainda causa metade do dano (exceto se o defensor usou uma reação para se esquivar). LIVRE INFECÇÃO: quem sofre dano das pancadas é infectado pelo vírus (Fortitude DT 30 evita); quem resiste fica imune até o fim da cena. REAÇÃO CONSUMAÇÃO INSIDIOSA: se reduzir um ser a 0 PV com as pancadas infectadas, consome a vítima e recupera 50 PV. COMPLETA ATROPELAR: percorre até o dobro do deslocamento passando pelo espaço de outros seres, atacando com pancada infectada cada um dos espaços por onde passar.", pagina = 267, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Perturbado de Energia", vd = "40", elemento = "Energia", defesa = 19, pv = 60, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 1, "int" to 0, "pre" to 0, "vig" to 0), ataques = "TESTE 4O+10 | DANO 2d12 Energia (Toque Plasmático, corpo a corpo x2)", detalhes = "IMPLANTAR CONFUSÃO: uma vez por rodada, tenta agarrar (teste 4O+10) um personagem que acabou de sofrer dano do toque plasmático; se conseguir, implanta memórias traumáticas — o alvo sofre 2d8 de dano mental (Vontade DT 15 reduz à metade) e recebe vulnerabilidade a dano de Energia até o fim da cena. Origem: uma alma enlouquecida de forma brusca e agressiva, cuja percepção da Realidade se esvai antes mesmo de perceber que não está viva.", pagina = 269, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Sukkalgir", vd = "160", elemento = "Conhecimento / Energia", defesa = 34, pv = 220, deslocamento = 9, atributos = mapOf("agi" to 3, "for" to 2, "int" to 3, "pre" to 3, "vig" to 2), ataques = "TESTE 3O+15 | DANO 2d12 mental (Mordida do Outro Lado, corpo a corpo x2)", detalhes = "AURA DESESPERADA: qualquer ser que comece o turno em alcance curto sofre 2d12 de dano mental (Vontade DT 25 reduz à metade). ESPÍRITO PLASMÁTICO: é parcialmente intangível, podendo atravessar obstáculos sólidos como paredes. LIVRE AGARRÃO: acertando a mordida em um ser Médio ou menor, pode agarrar (teste 3O+15). COMPLETA GRITO DE DESESPERO: grita em desespero; cada ser em alcance médio sofre 3d12 de dano mental (Vontade DT 20 reduz à metade; cobertura dá +5 no teste).", pagina = 269, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Telopsia", vd = "340", elemento = "Morte / Conhecimento", defesa = 48, pv = 560, deslocamento = 12, atributos = mapOf("agi" to 4, "for" to 2, "int" to 3, "pre" to 5, "vig" to 2), ataques = "TESTE 4O+35 | DANO 6d12+30 Energia (Toque Desintegrador, corpo a corpo x3)", detalhes = "MOVIMENTO VIAJAR PELA TELA: desmaterializa-se e se materializa em outra tela ou visor em alcance longo, deslocando-se 9m em seguida. PADRÃO TELA ZUMBIFICADORA: projeta imagens enlouquecedoras em sua tela; todos em alcance médio sofrem 6d6 de dano mental e ficam confusos até o fim da cena (Vontade DT 30 reduz o dano à metade e evita a condição); quem já está confuso e falha também fica fascinado. COMPLETA PRENDER NA TELA: desintegra um ser em alcance curto e o materializa dentro da tela (Fortitude DT 30 evita); o preso fica paralisado e sofre 2d12 de dano mental no início de cada turno; se o telopsia sofrer 50+ pontos de dano em um turno, o preso pode repetir o teste de Fortitude para escapar. ENIGMA DE MEDO: se a fita amaldiçoada que originou o telopsia for destruída, seus PV vão a 0 e ele é destruído; caso contrário, mesmo derrotado em combate, retornará se o Enigma não for resolvido.", pagina = 271, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Tempestuoso", vd = "360", elemento = "Energia", defesa = 56, pv = 950, deslocamento = 24, atributos = mapOf("agi" to 5, "for" to 4, "int" to 2, "pre" to 5, "vig" to 4), ataques = "TESTE 5O+40 | DANO 4d20+20 Energia (Garras Radioativas, corpo a corpo x2, também atinge alcance curto)", detalhes = "AURA RADIOATIVA: quem começa o turno em alcance curto sofre 2d20+20 de dano de Energia (Fortitude DT 40 reduz à metade). ESPECTRO RADIOATIVO: manifesta um espectro de radiação como extensão do corpo — todos os ataques e habilidades corpo a corpo podem ser feitos também em alcance curto. LIVRE RAIO DE ENERGIA RADIOATIVA: ao acertar dois ataques de garras no mesmo ser, projeta um raio de energia radioativa desse ser para outro alvo em alcance médio, causando 4d20+20 de dano de Energia (Reflexos DT 40 reduz à metade). COMPLETA EXPANDIR EM RADIAÇÃO: concentra e expande energia radioativa como explosão; todos em alcance longo sofrem 10d20+20 de dano de Energia (Reflexos DT 40 reduz à metade); o próprio tempestuoso perde 100 PV ao usar.", pagina = 273, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Viajante", vd = "200", elemento = "Conhecimento / Energia", defesa = 34, pv = 360, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 2, "int" to 3, "pre" to 4, "vig" to 2), ataques = "TESTE 4O+15 | DANO 2d12+10 impacto (Pancada, corpo a corpo x2)", detalhes = "INVISIBILIDADE PERMANENTE: é invisível, com camuflagem total, +15 em Furtividade, e seres que não podem vê-lo ficam desprevenidos contra seus ataques. LIVRE AGARRÃO: acertando a pancada em um ser Médio ou menor, pode agarrar (teste 2O+15). COMPLETA DEVORAR MEMÓRIA: entra na mente de um ser agarrado e devora suas memórias; a vítima sofre 4d12 de dano mental e esquece completamente uma pessoa (Vontade DT 29 reduz o dano à metade e evita o efeito); a cada ser deixado perturbado assim, o dano da pancada aumenta em +1d12 até o fim da cena. ENIGMA DE MEDO: só é possível enxergá-lo fotografando-o com um dispositivo de captura de imagem sem que ele esteja viajando através dela; quando resolvido, perde a Invisibilidade Permanente até o início do próximo turno de quem o capturou.", pagina = 274, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Degolificada", vd = "320", elemento = "Energia/Conhecimento/Sangue/Morte", defesa = 45, pv = 850, deslocamento = 6, atributos = mapOf("agi" to 3, "for" to 5, "int" to 3, "pre" to 4, "vig" to 4), ataques = "TESTE 5O+35 | DANO 8d8+20 impacto (Pancada, corpo a corpo x2)", detalhes = "CRIATURA DE MEDO: é imune a dano até que se resolva o mistério de sua origem — precisa ser confrontada com a causa de sua morte, sem poder escapar desse confronto; se confrontada assim, perde a imunidade a dano. AGARRAR E ESTRANGULAR: acertando a pancada em alvo Médio ou menor, pode agarrá-lo (teste 5O+35); enquanto agarrado, também fica asfixiado; mantém até duas criaturas agarradas. GRITO RASGADO: uma vez por cena, grito ensurdecedor que causa 4d10+10 de dano mental a todos em alcance médio e um efeito aleatório de surdez, temporária ou permanente, em um ou dois ouvidos (Vontade DT 35 reduz o dano à metade e evita o efeito). DESFIGURAMENTO CAPILAR: usa os cabelos para penetrar orifícios faciais de quem estiver agarrando, causando 10d6+20 de dano de perfuração (Fortitude DT 35 reduz à metade) e 6d10 de dano mental (Vontade DT 35 reduz à metade).", pagina = 282, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Bandido", vd = "10", elemento = "", defesa = 14, pv = 8, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 2, "int" to 1, "pre" to 1, "vig" to 1), ataques = "TESTE 2O+5 | DANO 1d4+2 perfuração (Faca, corpo a corpo)", detalhes = "ATAQUE FURTIVO: uma vez por rodada, causa +1d6 de dano com ataques corpo a corpo, ou à distância em alcance curto, contra alvos desprevenidos ou flanqueados. Um criminoso típico, como um ladrão ou assaltante.", pagina = 284, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Capanga", vd = "20", elemento = "", defesa = 13, pv = 17, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 2, "int" to 1, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+5 | DANO 1d8+7 impacto (Bastão, corpo a corpo); TESTE O+5, crítico 19/x3 | DANO 2d6+5 balístico (Revólver, distância curto)", detalhes = "LIVRE ATAQUE FURTIVO: uma vez por rodada, causa +2d6 de dano com ataques corpo a corpo, ou à distância em alcance curto, contra alvos desprevenidos ou flanqueados. Homens e mulheres embrutecidos que vivem pela violência, a serviço de mafiosos ou cultistas; pode representar membros de gangue, executores da máfia ou leões de chácara.", pagina = 284, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Policial", vd = "20", elemento = "", defesa = 19, pv = 15, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 2, "int" to 1, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+5 | DANO 1d8+7 impacto (Bastão, corpo a corpo); TESTE 2O+5, crítico 18 | DANO 1d12+5 balístico (Pistola, distância curto)", detalhes = "O policial padrão, encontrado patrulhando as ruas e praças da maioria das cidades. Provavelmente nunca teve um encontro com o paranormal e considera qualquer menção a monstros e magias uma brincadeira de mau gosto — ou uma desculpa para esconder algum crime. Esta ficha também pode representar vigias, seguranças corporativos e pessoas com algum treinamento com armas em geral.", pagina = 284, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Soldado de Aluguel", vd = "40", elemento = "", defesa = 18, pv = 25, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 2, "int" to 1, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+10, crítico 19 | DANO 1d6+9 corte (Machete, corpo a corpo); TESTE 2O+10, crítico 19/x3 | DANO 2d8+9 balístico (Fuzil de Assalto, distância médio)", detalhes = "ATAQUE EM MOVIMENTO: pode percorrer seu deslocamento e atacar em qualquer ponto durante o movimento. Um combatente profissional, que trabalha para quem pagar mais.", pagina = 284, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Assassino", vd = "80", elemento = "", defesa = 26, pv = 90, deslocamento = 9, atributos = mapOf("agi" to 4, "for" to 2, "int" to 3, "pre" to 3, "vig" to 2), ataques = "TESTE 4O+17, crítico 19 | DANO 1d4+11 corte (Faca, corpo a corpo x2); TESTE 4O+15, crítico 16/x4 | DANO 1d12+14 balístico (Pistola, distância curto x2)", detalhes = "EVASÃO: quando sofre um ataque que permite teste de Reflexos para reduzir o dano à metade, não sofre dano algum se passar. LIVRE ATAQUE FURTIVO: uma vez por rodada, causa +4d6 de dano com ataques corpo a corpo, ou à distância em alcance curto, contra alvos desprevenidos ou flanqueados. LIVRE MÃO NA BOCA: ao fazer um ataque corpo a corpo furtivo contra uma pessoa desprevenida, pode tentar agarrá-la (teste 2O+15); se conseguir, ela não pode falar enquanto estiver agarrada. MOVIMENTO ASSASSINAR: analisa um ser em alcance curto; até o fim do próximo turno, seu primeiro Ataque Furtivo que causar dano a esse alvo tem os dados de dano extras dobrados.", pagina = 285, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Comandante Mercenário", vd = "120", elemento = "", defesa = 29, pv = 145, deslocamento = 6, atributos = mapOf("agi" to 4, "for" to 2, "int" to 3, "pre" to 3, "vig" to 2), ataques = "TESTE 3O+17, crítico 19 | DANO 1d6+15 corte (Machete, corpo a corpo x2); TESTE 2O+17, crítico 19/x3 | DANO 3d12+15 balístico (Metralhadora, distância médio x2)", detalhes = "SADISMO: se causa dano em um inimigo, seu próximo ataque recebe +O no teste e, se acertar, causa mais um dado de dano do mesmo tipo. COMPLETA ATAQUE EM MOVIMENTO: pode percorrer o deslocamento e atacar em qualquer ponto durante o movimento, fazendo seus dois ataques corpo a corpo ou à distância. MOVIMENTO ORDENS: grita ordens para aliados em alcance médio, que recebem +O em testes de perícia e causam mais um dado de dano do mesmo tipo até o fim da cena.", pagina = 285, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Iniciado", vd = "20", elemento = "", defesa = 16, pv = 15, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 1, "int" to 2, "pre" to 2, "vig" to 1), ataques = "TESTE O, crítico 19 | DANO 1d4+1 corte (Faca, corpo a corpo)", detalhes = "CONJURADOR: escolhe dois rituais de 1º círculo de um elemento; pode conjurá-los sem pagar seu custo de PE, até um limite de 3 PE por conjuração, usando a ação apropriada para cada ritual. A DT para resistir aos seus rituais é 15. Ainda no caminho da adoração às entidades, mas já capaz de conjurar rituais — pode ser um oponente perigoso para agentes inexperientes.", pagina = 286, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Investido", vd = "40", elemento = "", defesa = 17, pv = 35, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 1, "int" to 2, "pre" to 2, "vig" to 1), ataques = "TESTE 2O+5, crítico 19 | DANO 1d4+1 corte (Faca, corpo a corpo); TESTE 2O, crítico 19/x3 | DANO 2d6 balístico (Revólver, distância curto)", detalhes = "CONJURADOR: escolhe dois rituais de 1º círculo e dois rituais de 2º círculo de até dois elementos; pode conjurá-los sem pagar seu custo de PE, até um limite de 5 PE por conjuração, usando a ação apropriada para cada ritual. A DT para resistir aos seus rituais é 17. Cultista que executou os ritos iniciais de admissão e provou lealdade ao seu Elemento — comprometido com as Entidades e um perigo para a Realidade.", pagina = 286, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Líder de Culto", vd = "140", elemento = "", defesa = 23, pv = 60, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 1, "int" to 2, "pre" to 2, "vig" to 1), ataques = "TESTE 2O+10, crítico 19 | DANO 1d4+1 corte (Faca, corpo a corpo); TESTE 2O+5, crítico 19/x3 | DANO 2d6 balístico (Revólver, distância curto)", detalhes = "CONJURADOR: escolhe dois rituais de 1º círculo, dois de 2º círculo e dois de 3º círculo, de até dois elementos; pode conjurá-los sem pagar seu custo de PE, até um limite de 10 PE por conjuração, usando a ação apropriada para cada ritual. A DT para resistir aos seus rituais é 25. Experiente e capaz de conjurar rituais mais poderosos, mantém habilmente seu disfarce de bom cidadão — pode ser qualquer um, até alguém próximo dos agentes.", pagina = 286, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Chefe de Polícia", vd = "100", elemento = "", defesa = 25, pv = 105, deslocamento = 9, atributos = mapOf("agi" to 2, "for" to 3, "int" to 2, "pre" to 3, "vig" to 3), ataques = "TESTE 3O+15 | DANO 1d8+8 impacto (Bastão, corpo a corpo x2); TESTE 2O+17, crítico x3 | DANO 4d6+12 balístico (Espingarda, distância curto x2)", detalhes = "TEIMOSO: uma vez por cena, pode ignorar um efeito que exija teste de resistência ou reduzir um dano recém-sofrido à metade. Um delegado ou coronel que já passou por situações difíceis e não se intimida facilmente.", pagina = 287, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Policial de Elite", vd = "60", elemento = "", defesa = 27, pv = 40, deslocamento = 6, atributos = mapOf("agi" to 3, "for" to 3, "int" to 1, "pre" to 1, "vig" to 3), ataques = "TESTE 3O+10 | DANO 1d8+13 impacto (Bastão, corpo a corpo x2); TESTE 3O+10, crítico 17/x3 | DANO 2d8+13 balístico (Fuzil de Assalto, distância médio)", detalhes = "FORTIFICAÇÃO: graças ao equipamento, tem 50% de chance de ignorar o dano adicional de um acerto crítico ou ataque furtivo. Possui resistência a balístico, corte, impacto e perfuração 5. PADRÃO LANÇA-GRANADAS: uma vez por cena, dispara uma granada explosiva em alcance médio; cada ser a 6m do ponto de impacto sofre 8d6 de dano de impacto (Reflexos DT 19 reduz à metade). COMPLETA EMPURRAR E ATIRAR: empurra um personagem adjacente 3m para longe (Fortitude DT 19 evita) e em seguida atira com o fuzil a curta distância; se conseguiu empurrar, o ataque recebe +O e, se acertar, +2d8 na rolagem de dano.", pagina = 287, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Cão de Guarda", vd = "10", elemento = "", defesa = 14, pv = 12, deslocamento = 12, atributos = mapOf("agi" to 2, "for" to 2, "int" to 0, "pre" to 1, "vig" to 2), ataques = "TESTE 2O+5 | DANO 1d6+2 corte (Mordida, corpo a corpo)", detalhes = "LIVRE DERRUBAR: se acerta um ataque de mordida, pode fazer a manobra derrubar (bônus OO+5). Cães treinados para guarda podem causar problemas a um grupo que precisa ser furtivo; a mesma ficha serve para cães policiais ou lobos.", pagina = 288, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Enxame de Abelhas", vd = "10", elemento = "", defesa = 15, pv = 10, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 0, "int" to 0, "pre" to 1, "vig" to 0), ataques = "", detalhes = "ENXAME: aglomeração que age em conjunto e pode ocupar o espaço de um ser; no fim do turno, causa 2d6 de dano de perfuração automaticamente a qualquer ser em seu espaço; é imune a manobras de combate e a efeitos que afetem apenas um ser sem causar dano, sofre metade do dano de armas, mas 50% a mais de dano de efeitos de área. ZUMBIDO NAUSEANTE: quem sofre dano do enxame fica enjoado por 1 rodada (Fortitude DT 15 evita). Normalmente pacíficas, tornam-se agressivas se a colmeia é ameaçada.", pagina = 288, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Enxame de Ratos", vd = "10", elemento = "", defesa = 13, pv = 15, deslocamento = 9, atributos = mapOf("agi" to 1, "for" to 0, "int" to 0, "pre" to 1, "vig" to 1), ataques = "", detalhes = "ENXAME: aglomeração que pode ocupar o espaço de um ser; no fim do turno, causa 2d6 de dano de perfuração automaticamente a qualquer ser em seu espaço; é imune a manobras de combate e a efeitos que afetam apenas um ser sem causar dano, sofre metade do dano de ataques com armas, mas 50% a mais de dano de efeitos de área. DOENÇA: quem sofre dano do enxame contrai a doença febre hemorrágica (Fortitude DT 15 evita).", pagina = 288, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Jacaré", vd = "40", elemento = "", defesa = 16, pv = 40, deslocamento = 6, atributos = mapOf("agi" to 1, "for" to 3, "int" to 0, "pre" to 1, "vig" to 2), ataques = "TESTE 3O+5 | DANO 1d8+8 corte (Mordida, corpo a corpo); TESTE 3O+5 | DANO 1d12 impacto (Cauda, corpo a corpo)", detalhes = "AGARRÃO: acertando a mordida em ser Médio ou menor, pode tentar agarrá-lo (teste 3O+7). GIRO DA MORTE: se estiver agarrando um ser dentro d'água e repetir a manobra de agarrar para causar dano, causa +2d8 de dano adicional. Espécime grande, capaz de ser encontrado até em áreas urbanas.", pagina = 288, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Javaporco", vd = "20", elemento = "Morte", defesa = 14, pv = 35, deslocamento = 12, atributos = mapOf("agi" to 1, "for" to 2, "int" to 0, "pre" to 1, "vig" to 3), ataques = "TESTE 2O+5 | DANO 1d8+4 corte (Mordida, corpo a corpo)", detalhes = "FEROCIDADE: se sofre dano, recebe +O em testes de ataque e causa um dado de dano adicional em todas as rolagens de dano até o final da cena. REAÇÃO MORDIDA FINAL: quando é reduzido a 0 PV, faz um ataque de mordida contra um oponente aleatório em seu alcance antes de morrer. Resultado do cruzamento de javalis com porcos domésticos, tornou-se uma praga em muitas regiões rurais.", pagina = 289, fonte = "Livro de Regras"),
    AmeacaPronta(nome = "Onça-Pintada", vd = "40", elemento = "", defesa = 16, pv = 55, deslocamento = 12, atributos = mapOf("agi" to 3, "for" to 3, "int" to 0, "pre" to 1, "vig" to 2), ataques = "TESTE 3O+10 | DANO 1d8+5 corte (Mordida, corpo a corpo); TESTE 3O+10, crítico 19 | DANO 1d6+5 corte (Garras, corpo a corpo x2)", detalhes = "AGARRÃO: acertando a mordida em ser Médio ou menor, pode tentar agarrá-lo (teste 3O+7). BOTE: investida com ataque de mordida e garras (três ataques) contra o mesmo alvo, todos com bônus de +O da investida. O maior felino das Américas e principal predador das selvas brasileiras.", pagina = 289, fonte = "Livro de Regras"),
